def enrich_copy(copy):
    for lang,c in copy.items():
        en=lang=='en'
        c['contactLabel']='06 / LET’S TALK' if en else '06 / KONTAKT'
        c['nav']=['Selected work','Experience','Expertise','Evidence','Contact'] if en else ['Projekte','Erfahrung','Kompetenzen','Nachweise','Kontakt']
        c['languageText']=('German B2 · English C1' if en else 'Deutsch B2 · Englisch C1')+'<br>Hindi · Gujarati · Sindhi'
        c['languageNote']='Working levels self-reported; German B1-plus course certificate available.' if en else 'Berufliche Selbsteinschätzung; B1-plus-Leistungsschein vorhanden.'
        c['degrees'][0][2]+=' · '+('Grade 1.8 · ECTS B' if en else 'Note 1,8 · ECTS B')
        c['degrees'][1][2]+=' · CGPA 8.14/10'
        c['degrees'][2][2]+=' · CGPA 9.50/10'
        c['projects'][1]['result']=('The September 2026 employer reference confirms independent product development, drawing and sheet-metal development, Inventor CAD and complex assemblies. Cost, weight and volume metrics are not established by this reference and are omitted.' if en else 'Das Arbeitszeugnis vom September 2026 bestätigt eigenverantwortliche Produktentwicklung, Zeichnungs- und Abwicklungserstellung, Inventor-CAD und komplexe Baugruppen. Kosten-, Gewichts- und Mengenkennzahlen werden dadurch nicht belegt und bleiben ungenannt.')
        c['projects'][1]['note']='Source: NeSt employment reference, 30 September 2026. Conceptual illustration.' if en else 'Quelle: NeSt-Arbeitszeugnis vom 30. September 2026. Schematische Illustration.'
        c['projects'][0]['note']+=' '+('Employer reference separately states 20% cost reduction.' if en else 'Das Arbeitgeberzeugnis nennt gesondert 20 % Kostenreduktion.')
        c['projects'][3]['short']='An academic cylindrical handling mechanism with rotary motion, a vertical prismatic axis and a pick-and-place gripper.' if en else 'Ein akademischer zylindrischer Handhabungsmechanismus mit Drehbewegung, vertikaler Linearachse und Pick-and-Place-Greifer.'
        c['projects'][3]['approach']='Developed the cylindrical mechanism, CAD assemblies, gripper linkage, actuator selection and supporting stress/bending calculations in Autodesk Inventor.' if en else 'Zylindrischen Mechanismus, CAD-Baugruppen, Greiferkinematik, Aktuatorauswahl sowie Spannungs- und Biegeberechnungen in Autodesk Inventor erarbeitet.'
        c['jobs'][0][2]='Mechanical Design Engineer · Konstrukteur' if en else 'Konstrukteur'
        c['jobs'][0][4]='Employer reference confirms drawings, sheet-metal developments, Autodesk Inventor assemblies, independent product development and digital documentation.' if en else 'Arbeitszeugnis bestätigt Zeichnungs- und Abwicklungserstellung, Inventor-Baugruppen, eigenverantwortliche Produktentwicklung und digitale Dokumentation.'
        # A supplied editable draft says March; older CV says February. No issued student reference resolves it.
        c['jobs'][1][0]='2024 · '+('until June' if en else 'bis Juni')
        c['jobs'][3][0]='2020–2021'
        c['experienceNote']='Issued references support the NeSt role and Brooks internship. The 2024 student-role start month and Ravi departure month differ between supplied sources, so exact months are not asserted.' if en else 'Ausgestellte Zeugnisse belegen die NeSt-Tätigkeit und das Brooks-Praktikum. Beginn der Werkstudententätigkeit 2024 und Austrittsmonat bei Ravi weichen zwischen Quellen ab; genaue Monate werden daher nicht behauptet.'
        for p in (new_projects_en() if en else new_projects_de()):c['projects'].append(p)

